-- Add subtitle, category, and is_original fields to douleurs table
-- so that all encyclopédie topics can be managed from the backoffice

ALTER TABLE douleurs ADD COLUMN IF NOT EXISTS subtitle text;
ALTER TABLE douleurs ADD COLUMN IF NOT EXISTS category text;
ALTER TABLE douleurs ADD COLUMN IF NOT EXISTS is_original boolean DEFAULT false;

-- Update existing douleurs that match known original topics
-- (they'll get their subtitle/category set via the admin panel or seed below)

-- Seed all 170+ encyclopédie topics as douleurs entries
-- Uses ON CONFLICT to avoid duplicating existing entries (matched by slug)
-- Existing douleurs keep their content; new ones are created as placeholders

-- First ensure slug has a unique constraint for upsert
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'douleurs_slug_unique'
  ) THEN
    ALTER TABLE douleurs ADD CONSTRAINT douleurs_slug_unique UNIQUE (slug);
  END IF;
END $$;

ON CONFLICT (slug) DO UPDATE SET
  subtitle = COALESCE(EXCLUDED.subtitle, douleurs.subtitle),
  category = COALESCE(EXCLUDED.category, douleurs.category),
  is_original = COALESCE(EXCLUDED.is_original, douleurs.is_original);
